// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "Blue"

const N_ANIM = 25; // how long the animation stage lasts
const N_WAIT = 75; // how long the wait stage lasts

let n = 25; // size of the grid (should be an odd multiple of the length of the palette)
let margin = 50;
let colors = [...Array(n)].map((e) => Array(n));
let weights1 = []; // weights of first compo
let weights2 = []; // weights of second compo

function setup() {
	createCanvas(500, 500);
	noStroke();

	let palette = ["#203051", "#4464a1", "#62b6de", "#b3dce0", "#e2f0f3"];
	let pl = palette.length;
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			colors[i][j] = palette[(i+j)%pl];
			if (i > n/2 && j < n/2) colors[i][j] = palette[(pl-1+sq(n)-i+j)%pl];
			if (i < n/2 && j > n/2) colors[i][j] = palette[(pl-1+sq(n)+i-j)%pl];
			if (i > n/2 && j > n/2) colors[i][j] = palette[(pl-2+sq(n)-i-j)%pl];
		}
	}

	for (let i = 0; i < n; i++) {
		let w1 = ~~(n/2)-i+1;
		if (i > n/2) w1 = i-~~(n/2)+1;
		w1 = sq(w1)+5;
		weights1.push(w1);
		let w2 = i+1;
		if (i > n/2) w2 = n-i;
		w2 = sq(w2)+5;
		weights2.push(w2);
	}
}

function draw() {
	background("#fffbe6");

	let firstHalf = frameCount%(2*N_ANIM+2*N_WAIT) < N_ANIM + N_WAIT;

	let lerpedWeights = [];
	let wSum = 0, hSums = [];
	for (let i = 0; i < n; i++) {
		let weightsLine = [];

		let offset = 5*abs(i-n/2+1/2);
		let t, f = (frameCount+offset)%(2*N_ANIM+2*N_WAIT);
		if (f < N_WAIT) t = 0;
		else if (f < N_ANIM+N_WAIT) t = easeInOutQuint(((f-N_WAIT)%N_ANIM)/N_ANIM);
		else if (f < N_ANIM+2*N_WAIT) t = 1;
		else t = 1-easeInOutQuint(((f-N_ANIM-2*N_WAIT)%N_ANIM)/N_ANIM);

		let w = lerp(weights1[i], weights2[i], t);
		wSum += w;
		let hSum = 0;
		for (let j = 0; j < n; j++) {
			let h = lerp(weights1[j], weights2[j], t);
			hSum += h;
			weightsLine.push([w, h]);
		}
		hSums.push(hSum);
		lerpedWeights.push(weightsLine);
	}

	let x = margin;
	let uw = (width-2*margin)/wSum;
	for (let i = 0; i < n; i++) {
		let y = margin;
		let uh = (height-2*margin)/hSums[i];
		var w = lerpedWeights[i][0][0]*uw;
		for (let j = 0; j < n; j++) {
			var h = lerpedWeights[i][j][1]*uh;
			fill(colors[i][j]);
			if (firstHalf) rect(y, x, h, w);
			else rect(x, y, w, h);
			y += h;
		}
		x += w;
	}
}

// from easings.net
function easeInOutQuint(x) {
	return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}
